) AS (
  VALUES 
    (616::BIGINT, 'Demasiado metiche y pasaba hablando mal de una muchacha cuando lo llevé yo. No entiendo por qué un profesor tomaría la posición de él y mucho menos que la demuestre en frente de una como compañera. Hay que ir a consulta. Personalidad pesada'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2026-08-25T00:00:00+00:00'::TIMESTAMPTZ, '16722e2f0b0c35518c164ffd1dfb5c46bb42f140fa142fdbdcf06ead9479c5b3'::TEXT, ARRAY[1852, 1859]::BIGINT[]),
    (616::BIGINT, 'Es muy pero muy favoritista, si usted no fue a consulta y entregó lo mismo que su compañero que si, ud tiene un 70 y su compañero un 100, explica mal la verdad, no sabe comunicar, para pasar el curso es ganándoselo porque como tal lo que enseña no es diseño de calidad (su cronograma lo demuestra)'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '374eeb2c82e52db887b6cc17510d6a632c3382e9d25cbf3f95d89be56e093416'::TEXT, ARRAY[1852]::BIGINT[]),
    (616::BIGINT, 'Terrible. Cero comprensivo con situaciones personales. No se adhiere a los apoyos educativos que se solicitan. Muy grosero y apático. Cero paciencia. Califica como le da la gana, a pesar de implementar rubricas, no se adhiere a ellas.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2026-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'c971cff507a5c94d991d2bdfed835fad86ce3395a373c98d879399735bd31b61'::TEXT, ARRAY[1852]::BIGINT[]),
    (616::BIGINT, 'CONSULTA es la clave para pasar. Como en todo curso se aprende algo, pero es algo que se puede llevar virtual y hasta rinde más el tiempo, obviamente hay preferencias en estudiantes sin entrar en detalles...'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-09-06T00:00:00+00:00'::TIMESTAMPTZ, 'c2749df827fe71db49b0715d4fcf6a697d13c4eb44b5e907be07fa5e3934c5cc'::TEXT, ARRAY[1852, 1859]::BIGINT[]),
    (616::BIGINT, 'todo es pasable con él, mientras lleve todo al día (VAYA A CONSULTA!!!). Sí tiende a hacer algunas cosas mucho menos interesantes de lo que podrían ser, sobretodo en visual, que es muy cuadrado. Vaya. a. consulta. si quiere buena nota'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Brinda apoyo']::TEXT[], '2024-12-11T00:00:00+00:00'::TIMESTAMPTZ, '71525891091488a7b9cf26dcc60763797e9a736882e88f8e76b42d9e94c5882a'::TEXT, ARRAY[1852, 1859]::BIGINT[]),
    (616::BIGINT, 'Es de los peores profesores que he tenido en mi vida, si no es que el peor. No se le entiende nada y califica como se le da la gana. Los trabajos son aburridos y uno casi no aprende e inclusive, puede perder por completo interés en la clase. Hay que rogarle para que explique cosas, mucha suerte.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2024-11-04T00:00:00+00:00'::TIMESTAMPTZ, 'c6a345b7e57c8a406855ed491ad1c72972d8e8b356198c714aef4142c54a64e5'::TEXT, ARRAY[1852, 1859]::BIGINT[]),
    (616::BIGINT, 'Califica como le dá la gana, no sigue rúbricas y todo lo que haga uno tiene que ser como él quiera. Aquí no vale tanto la creatividad, los trabajos de todos siempre son iguales y realmente no destacan en nada. Redundante explicando y siempre le encuentra algo a los trabajos. Muchos éxitos.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-05-22T00:00:00+00:00'::TIMESTAMPTZ, '26e913716d542d897f42c418b60b2883fbd65185ecadd32cc6259692ad79c30e'::TEXT, ARRAY[1852]::BIGINT[]),
    (616::BIGINT, 'El profe es super bueno, es muy importante ir a las clases y tomar apuntes para que los trabajos se entiendan mejor, pero ayuda mucha en consultas así que vayana cada que puedan :)'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2023-06-22T00:00:00+00:00'::TIMESTAMPTZ, '7394dcc39e29368ce20562bcbb2b50febf03b12df5da3188e4b2d4927a68f74e'::TEXT, ARRAY[1852]::BIGINT[]),
    (616::BIGINT, 'Fácilmente uno de los mejores profesores de diseño. No le molesta compartir su conocimiento con la clase, sus trabajos están repletos de instrucciones claras y ordenadas, brinda mucho consejo en consulta, es comprensivo y siempre busca un acuerdo entre estudiante-profesor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-03-16T00:00:00+00:00'::TIMESTAMPTZ, 'ef29ee2cc50f472a3e5ddd4b6bce800fcba601ed1071084880ba45619ee14f91'::TEXT, ARRAY[1852]::BIGINT[]),
    (616::BIGINT, 'El profe es excelente, lo único es que algunos aspectos de evaluación no son tan claros. Ayuda y escucha si es necesario.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Respetado por los estudiantes']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'eaa4c46b79b1169b6c7f0ed228b133b09f46955ac70feb3c6c79997a74ba6d58'::TEXT, ARRAY[1859]::BIGINT[]),
    (616::BIGINT, 'Excelente profesor, excelente forma de adaptarse a la virtualidad. Da mucha retroalimentación y dispuesto a ayudar a los estudiantes. Aproveche la consulta.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, 'de2455d19f360294238fd3e951f9abdffe93be3f29d20726371c9e9470637212'::TEXT, ARRAY[1852]::BIGINT[]),
    (616::BIGINT, 'Da muhco apoyo y guía con los trabajos, se adaptó muy bien a la modalidad virtual. Es muy comprensivo siempre y cuando uno demuestre que se está esforzando y que le importa el curso. Vayan a consulta!! Nunca bota las ideas que uno le tenga, da muy buena retroalimentación.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2020-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'bd6a5ebb43a42e3ec945970b2261fee4a20bdbcbb9229fe8f0bb11b249e07150'::TEXT, ARRAY[1852]::BIGINT[]),
    (616::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'dc27bed909754a632f79a3d2d5122da91bab02f937125a57a6abb8711a0c1afd'::TEXT, ARRAY[1852]::BIGINT[]),
    (616::BIGINT, 'Es un profe que busca ayudar al estudiante, pero a veces no es tan claro y puede ser subjetivo en cuanto a cómo retroalimenta o califica'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Muchos proyectos grupales']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'f71c5df76c9e8b8afddbde781a5aed924a6ddbdc8eb729dd0b2ff8fad917b278'::TEXT, ARRAY[1852]::BIGINT[]),
    (616::BIGINT, 'Hace los mismos trabajos desde hace como 10 años. Demasiado anticuado, su curso no está actualizado con la comunicación visual de hoy en día. Habla demasiada paja en clases. Sabe bastante, pero es muy aburrido llevar su clase.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'a389627b088db560c597b35072344c91272fcb6dceb2483330b58ca0bb739f08'::TEXT, ARRAY[1852]::BIGINT[]),
    (616::BIGINT, 'La mejor opción, muy claro con las correcciones y lo que quiere en general. El ambiente de la clase es bueno, se pasa bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-13T00:00:00+00:00'::TIMESTAMPTZ, '64c754389635be531b2a58f53f541b3bca80694df77b7a256021b25085600a2d'::TEXT, ARRAY[1859, 1884]::BIGINT[]),
    (616::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-29T00:00:00+00:00'::TIMESTAMPTZ, '0df5cef7c560d8e36a598719ee8fc487b5f2eb402453a0c1fa92152adfb60e0a'::TEXT, ARRAY[1852]::BIGINT[]),
    (616::BIGINT, 'Tuvimos suerte en poder matricular este curso con Leo. Es el tipo de profesor objetivo que te apoya con cualquier idea que le llevés siempre y cuando la desarrollés de manera adecuada. Fue ameno llevar un curso tan parido con él.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2019-01-17T00:00:00+00:00'::TIMESTAMPTZ, '1a8f1569d5a780dac5ef894fc5c8728c928100c94a3c86d5ee4dfa35c473763b'::TEXT, ARRAY[1868]::BIGINT[]),
    (616::BIGINT, 'De los mejores profesores de la carrera. El indicado para impartir el curso de Diseño 1. Un profesor que siempre es muy claro y directo. Altamente recomendado!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-07-16T00:00:00+00:00'::TIMESTAMPTZ, '60cee9341a132ced41a039ad739c77e7993eb3a5d443b3a1095a067c5fa5d057'::TEXT, ARRAY[1859]::BIGINT[]),
    (616::BIGINT, 'Él es muy directo, te dice las cosas sin asco, la clase es divertida, se aprende mucho, es claro con lo que quiere y si quiere un 100 de fijo en sus trabajos vaya a consulta.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-27T00:00:00+00:00'::TIMESTAMPTZ, '0bb9beabfda96e0b4a51b921876f7c5943489bbfbfd5f9b587654aafee1c4af3'::TEXT, ARRAY[1867]::BIGINT[]),
    (616::BIGINT, 'Leo es tal vez el profe más adecuado para Diseño I. Ayuda mucho en las consultas, le dice las cosas sin rodeos y le ayuda a mejorar bastante. La característica más buena de él como profesor es que es conciso y claro con lo que quiere y no es como otros profes de la escuela que son medio bipolares.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2018-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'c90ade19900b8bcf059cd8a21e77d9a43c034a906af60bfb94e24548fdfac9ae'::TEXT, ARRAY[1859]::BIGINT[]),
    (616::BIGINT, 'Excelente profe. Objetivo y fundamentado. Es directo con las cosas. De los mejores profes de la escuela sin duda alguna.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, '5ab72e398037bf93379ab01d52044d45b45d87edfd3ecf14f44cfca3c84df930'::TEXT, ARRAY[1936]::BIGINT[]),
    (616::BIGINT, '"A lo que vinimos" Un muy buen profe que se anda sin rodeos, buena gente y agradable. Es muy directo y explicito con las cosas que se quieren del curso. Super recomendado.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-22T00:00:00+00:00'::TIMESTAMPTZ, '3706c3a33535227cbfd787933b8c002edf6c9008ed82b90bad4d8b0a7276930f'::TEXT, ARRAY[1931]::BIGINT[]),
    (616::BIGINT, 'Le agradezco a este profe por salvar lo mal que iba el curso de Repre I haha. No haga caso a los comentarios que dicen que ayuda más a las mujeres. A todos los califica por igual y si considera que usted puede dar más, lo va a calificar más duro. Si usted como mae le pide ayuda, el mae ayuda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, '96a20fa629b59c74ebf74e40a1c3c44dd54ed55a68955ba49a817e97eb99c957'::TEXT, ARRAY[1859]::BIGINT[]),
    (616::BIGINT, 'Un buen profesor, podrá ser un poco más inclinado a ayudar a las mujeres pero califica muy parejo y se preocupa por su avance si ve que usted le pone bastante. La clase es amena y califica regular, entregue trabajos bien presentados.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'fccea18b3bcf944917f1e8abec48feec53e8611b6bbcf4cf8338098d475553c3'::TEXT, ARRAY[1859]::BIGINT[]),
    (616::BIGINT, 'Si es mujer y está rica, ya pasó. No sabe explicar y es bastante hijueputa en especial con los hombres. Si ud le pregunta otra vez, no sabe explicar la materia de otra forma distinta. Califica muy duro y sabe poco y uno aprende nada.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-16T00:00:00+00:00'::TIMESTAMPTZ, '03f06ad3a242ce9c5bdc81d57012cc6d2b3ed703ae0f4c3741a1217709c28fde'::TEXT, ARRAY[1927, 1931]::BIGINT[]),
    (616::BIGINT, 'Muy claro con lo que se quiere, se preocupa por el trabajo de cada estudiante, es comprensivo con la carga académica que uno lleva e intenta ayudar pero siempre uno es el que debe desarrollar el proyecto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-08-07T00:00:00+00:00'::TIMESTAMPTZ, 'c43f8f1852f0d4c419e5344e9071d730dc607d0a3051880848e055e512cc6911'::TEXT, ARRAY[1859]::BIGINT[]),
    (616::BIGINT, 'Es fácil con el hombre o mujer, lleve ordenado y bien presentados los trabajos, las clases es prácticamente lo mismo todos los días y va subiendo un poco la dificultad pero nada del otro mundo'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, '5f367e747811467f606eeed2663ade8c67f7f3c8998c2a5613d07b0a8ba2f074'::TEXT, ARRAY[1927, 1936]::BIGINT[]),
    (616::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-30T00:00:00+00:00'::TIMESTAMPTZ, '9c1db45080b148dee40c2ff6332ae116e06b2f9c1ea6011fe2bb593d30461c4d'::TEXT, ARRAY[1936, 1931, 1927]::BIGINT[]),
    (616::BIGINT, 'Si sos mujer punto a favor, si no ponga atencion y trate de entender lo que quiere explicar'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-02T00:00:00+00:00'::TIMESTAMPTZ, 'ec939c397361594de4ad57b199fed642dee57ce864324bc13dcd4eba770a05a4'::TEXT, ARRAY[1931, 1936]::BIGINT[]),
    (616::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-01T00:00:00+00:00'::TIMESTAMPTZ, '6509cbb57549721f5ae5cfb99b35427baf9ad754815bd8e70e5e76c13a9a5ce4'::TEXT, ARRAY[1925, 1929, 1933]::BIGINT[]),
    (616::BIGINT, 'Es buen profe, explica claro y ayuda bastante'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'ba94da29de3547777d66d59a8d452acb0918547c9ec821ddf5d72a0dee89fd26'::TEXT, ARRAY[1936, 1931, 1927]::BIGINT[]),
    (616::BIGINT, 'Si usted es hombre esta fregado, el mae lo califica a uno duro, si es mujer y le coquetea fijo pasa sobrada, el mae en muchas clases se preocupa mas por las estudiantes q por la materia, las clases carecen de planeacion y son reinterativas de cursos que dio antes. Recomendación use ropa sexy para el'::TEXT, 10.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-24T00:00:00+00:00'::TIMESTAMPTZ, '42bf5ab283f3a721306db9accd5614c946bc212810a31ae934301fe28d9204b6'::TEXT, ARRAY[1936, 1931, 1927]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
